fn diff(&self, base: &PdfSnapshot) -> MutationOutcome<PdfDiff> {
    if support::admitted_first_page(base).is_none() { return MutationOutcome::refuse("mutation.target-missing", "DPartRoot requires a genuine reachable Page", ["DPartRoot"]); }
    let mut next = base.clone();
    if !support::set_dpart_root(&mut next, &self.job) { return MutationOutcome::refuse("mutation.target-missing", "DPartRoot requires a genuine reachable Page", ["DPartRoot"]); }
    let catalog = next.trailer.iter().find(|entry| entry.key == "Root").and_then(|entry| entry.value.as_ref()).expect("admitted actual Catalog");
    let root = support::object(&next, catalog).and_then(|value| value.dict_get("DPartRoot")).expect("authored partition root").clone();
    if let Some(entry) = next.catalog_extra.iter_mut().find(|entry| entry.key == "DPartRoot") { entry.value = root; }
    else { next.catalog_extra.push(crate::standards::v1_7::subsets::base::schema::snapshot::PdfDictEntry::new("DPartRoot", root)); }
    MutationOutcome::new(PdfDiff { raw_graph: Some(crate::standards::v1_7::subsets::base::schema::diff::PdfRawGraph { objects: next.objects, catalog_extra: next.catalog_extra }), ..Default::default() })
}

fn inverse(&self, base: &PdfSnapshot) -> Result<Vec<PdfVtMutation>, semio_framework_value::ValueError> {
    if support::admitted_first_page(base).is_none() { return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "DPartRoot requires a genuine reachable Page")); }
    Ok(vec![PdfVtMutation::RestoreDpartGraph(super::restore_dpart_graph::RestoreDpartGraph { graph: crate::standards::v1_7::subsets::base::schema::diff::PdfRawGraph { objects: base.objects.clone(), catalog_extra: base.catalog_extra.clone() } })])
}

